1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	  <meta charset="UTF-8" />
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
6	  <title>待办清单 · Todo</title>
7	  <style>
8	    :root {
9	      --bg: #f4f5f7;
10	      --card: #ffffff;
11	      --primary: #4f6ef7;
12	      --primary-dark: #3d55d6;
13	      --danger: #e5534b;
14	      --text: #1f2328;
15	      --muted: #8b949e;
16	      --border: #e4e7ec;
17	      --done: #9aa4af;
18	    }
19	
20	    * {
21	      box-sizing: border-box;
22	      margin: 0;
23	      padding: 0;
24	    }
25	
26	    body {
27	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", sans-serif;
28	      background: var(--bg);
29	      color: var(--text);
30	      min-height: 100vh;
31	      display: flex;
32	      align-items: center;
33	      justify-content: center;
34	      padding: 24px;
35	    }
36	
37	    .card {
38	      background: var(--card);
39	      width: 100%;
40	      max-width: 480px;
41	      border-radius: 16px;
42	      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.06);
43	      padding: 28px;
44	    }
45	
46	    h1 {
47	      font-size: 22px;
48	      margin-bottom: 4px;
49	    }
50	
51	    .subtitle {
52	      color: var(--muted);
53	      font-size: 13px;
54	      margin-bottom: 20px;
55	    }
56	
57	    .input-row {
58	      display: flex;
59	      gap: 8px;
60	      margin-bottom: 18px;
61	    }
62	
63	    #todo-input {
64	      flex: 1;
65	      padding: 10px 14px;
66	      border: 1px solid var(--border);
67	      border-radius: 8px;
68	      font-size: 15px;
69	      outline: none;
70	      transition: border-color 0.15s;
71	    }
72	
73	    #todo-input:focus {
74	      border-color: var(--primary);
75	    }
76	
77	    #add-btn {
78	      background: var(--primary);
79	      color: #fff;
80	      border: none;
81	      border-radius: 8px;
82	      padding: 10px 18px;
83	      font-size: 15px;
84	      cursor: pointer;
85	      transition: background 0.15s;
86	    }
87	
88	    #add-btn:hover {
89	      background: var(--primary-dark);
90	    }
91	
92	    .toolbar {
93	      display: flex;
94	      justify-content: space-between;
95	      align-items: center;
96	      font-size: 13px;
97	      color: var(--muted);
98	      margin-bottom: 10px;
99	    }
100	
101	    #clear-done {
102	      background: none;
103	      border: none;
104	      color: var(--muted);
105	      font-size: 13px;
106	      cursor: pointer;
107	      text-decoration: underline;
108	    }
109	
110	    #clear-done:hover {
111	      color: var(--danger);
112	    }
113	
114	    ul {
115	      list-style: none;
116	    }
117	
118	    li {
119	      display: flex;
120	      align-items: center;
121	      gap: 10px;
122	      padding: 12px 8px;
123	      border-bottom: 1px solid var(--border);
124	    }
125	
126	    li:last-child {
127	      border-bottom: none;
128	    }
129	
130	    li input[type="checkbox"] {
131	      width: 18px;
132	      height: 18px;
133	      cursor: pointer;
134	      accent-color: var(--primary);
135	    }
136	
137	    li .text {
138	      flex: 1;
139	      font-size: 15px;
140	      word-break: break-word;
141	    }
142	
143	    li.done .text {
144	      color: var(--done);
145	      text-decoration: line-through;
146	    }
147	
148	    li .delete {
149	      background: none;
150	      border: none;
151	      color: var(--muted);
152	      font-size: 16px;
153	      cursor: pointer;
154	      line-height: 1;
155	      padding: 4px;
156	      border-radius: 6px;
157	    }
158	
159	    li .delete:hover {
160	      color: var(--danger);
161	    }
162	
163	    .empty {
164	      text-align: center;
165	      color: var(--muted);
166	      font-size: 14px;
167	      padding: 24px 0;
168	    }
169	  </style>
170	</head>
171	<body>
172	  <main class="card">
173	    <h1>待办清单</h1>
174	    <p class="subtitle">添加、勾选、删除，刷新后依然保留。</p>
175	
176	    <div class="input-row">
177	      <input id="todo-input" type="text" placeholder="要做点什么？" autocomplete="off" />
178	      <button id="add-btn">添加</button>
179	    </div>
180	
181	    <div class="toolbar">
182	      <span id="counter">共 0 项，未完成 0 项</span>
183	      <button id="clear-done">清除已完成</button>
184	    </div>
185	
186	    <ul id="todo-list"></ul>
187	    <p class="empty" id="empty-tip">暂无待办，先添加一条吧。</p>
188	  </main>
189	
190	  <script>
191	    (function () {
192	      const STORAGE_KEY = "todo-list-items";
193	      const listEl = document.getElementById("todo-list");
194	      const inputEl = document.getElementById("todo-input");
195	      const addBtn = document.getElementById("add-btn");
196	      const counterEl = document.getElementById("counter");
197	      const clearDoneBtn = document.getElementById("clear-done");
198	      const emptyTip = document.getElementById("empty-tip");
199	
200	      let items = load();
201	
202	      function load() {
203	        try {
204	          const raw = localStorage.getItem(STORAGE_KEY);
205	          return raw ? JSON.parse(raw) : [];
206	        } catch (e) {
207	          return [];
208	        }
209	      }
210	
211	      function save() {
212	        localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
213	      }
214	
215	      function addItem(text) {
216	        const trimmed = text.trim();
217	        if (!trimmed) return;
218	        items.push({ id: Date.now(), text: trimmed, done: false });
219	        save();
220	        render();
221	      }
222	
223	      function toggleItem(id) {
224	        const item = items.find((it) => it.id === id);
225	        if (item) {
226	          item.done = !item.done;
227	          save();
228	          render();
229	        }
230	      }
231	
232	      function deleteItem(id) {
233	        items = items.filter((it) => it.id !== id);
234	        save();
235	        render();
236	      }
237	
238	      function clearDone() {
239	        items = items.filter((it) => !it.done);
240	        save();
241	        render();
242	      }
243	
244	      function render() {
245	        listEl.innerHTML = "";
246	        items.forEach((item) => {
247	          const li = document.createElement("li");
248	          if (item.done) li.className = "done";
249	
250	          const checkbox = document.createElement("input");
251	          checkbox.type = "checkbox";
252	          checkbox.checked = item.done;
253	          checkbox.addEventListener("change", () => toggleItem(item.id));
254	
255	          const text = document.createElement("span");
256	          text.className = "text";
257	          text.textContent = item.text;
258	
259	          const del = document.createElement("button");
260	          del.className = "delete";
261	          del.textContent = "×";
262	          del.title = "删除";
263	          del.addEventListener("click", () => deleteItem(item.id));
264	
265	          li.appendChild(checkbox);
266	          li.appendChild(text);
267	          li.appendChild(del);
268	          listEl.appendChild(li);
269	        });
270	
271	        const total = items.length;
272	        const remaining = items.filter((it) => !it.done).length;
273	        counterEl.textContent = "共 " + total + " 项，未完成 " + remaining + " 项";
274	        emptyTip.style.display = total === 0 ? "block" : "none";
275	      }
276	
277	      addBtn.addEventListener("click", () => {
278	        addItem(inputEl.value);
279	        inputEl.value = "";
280	        inputEl.focus();
281	      });
282	
283	      inputEl.addEventListener("keydown", (e) => {
284	        if (e.key === "Enter") {
285	          addItem(inputEl.value);
286	          inputEl.value = "";
287	        }
288	      });
289	
290	      clearDoneBtn.addEventListener("click", clearDone);
291	
292	      render();
293	    })();
294	  </script>
295	</body>
296	</html>
