function clearDone() {
  items = items.filter((it) => !it.done);
  save();
  render();
}

function startEdit(id) {
  editingId = id;
  render();
  const input = listEl.querySelector(".edit-input");
  if (input) {
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
  }
}

function commitEdit(id, text) {
  const trimmed = text.trim();
  const item = items.find((it) => it.id === id);
  if (item && trimmed) {
    item.text = trimmed;
    save();
  }
  editingId = null;
  render();
}

function visibleItems() {
  if (filter === "active") return items.filter((it) => !it.done);
  if (filter === "done") return items.filter((it) => it.done);
  return items;
}

function render() {
  listEl.innerHTML = "";
  const visible = visibleItems();

  visible.forEach((item) => {
    const li = document.createElement("li");
    if (item.done) li.className = "done";

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = item.done;
    checkbox.addEventListener("change", () => toggleItem(item.id));

    li.appendChild(checkbox);

    if (item.id === editingId) {
      const editInput = document.createElement("input");
      editInput.type = "text";
      editInput.className = "edit-input";
      editInput.value = item.text;
      editInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter") commitEdit(item.id, editInput.value);
        if (e.key === "Escape") {
          editingId = null;
          render();
        }
      });
      editInput.addEventListener("blur", () => commitEdit(item.id, editInput.value));
      li.appendChild(editInput);
    } else {
      const text = document.createElement("span");
      text.className = "text";
      text.textContent = item.text;
      text.title = "双击编辑";
      text.addEventListener("dblclick", () => startEdit(item.id));
      li.appendChild(text);

      const edit = document.createElement("button");
      edit.className = "edit";
      edit.textContent = "编辑";
      edit.title = "编辑";
      edit.addEventListener("click", () => startEdit(item.id));
      li.appendChild(edit);
    }

    const del = document.createElement("button");
    del.className = "delete";
    del.textContent = "×";
    del.title = "删除";
    del.addEventListener("click", () => deleteItem(item.id));
    li.appendChild(del);

    listEl.appendChild(li);
  });

  filtersEl.querySelectorAll("button").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.filter === filter);
  });

  const total = items.length;
  const remaining = items.filter((it) => !it.done).length;
  counterEl.textContent = "共 " + total + " 项，未完成 " + remaining + " 项";
  emptyTip.style.display = visible.length === 0 ? "block" : "none";
  emptyTip.textContent =
    total === 0
      ? "暂无待办，先添加一条吧。"
      : filter === "active"
      ? "没有进行中的待办。"
      : "没有已完成的待办。";
}

